DECLARE
V_COUNT INTEGER;
BEGIN
SELECT COUNT(TABLE_NAME) INTO V_COUNT from USER_TABLES where TABLE_NAME = '__EFMigrationsHistory';
IF V_COUNT = 0 THEN
Begin
BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"__EFMigrationsHistory" (
    "MigrationId" NVARCHAR2(150) NOT NULL,
    "ProductVersion" NVARCHAR2(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
)';
END;

End;

END IF;
EXCEPTION
WHEN OTHERS THEN
    IF(SQLCODE != -942)THEN
        RAISE;
    END IF;
END;
/

BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"TUTORES" (
    "Id" NUMBER(10) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "Nome" NVARCHAR2(2000) NOT NULL,
    "Email" NVARCHAR2(2000) NOT NULL,
    "Telefone" NVARCHAR2(2000) NOT NULL,
    CONSTRAINT "PK_TUTORES" PRIMARY KEY ("Id")
)';
END;
/

BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"PETS" (
    "Id" NUMBER(10) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "Nome" NVARCHAR2(2000) NOT NULL,
    "Especie" NVARCHAR2(2000) NOT NULL,
    "Raca" NVARCHAR2(2000) NOT NULL,
    "DataNascimento" TIMESTAMP(7) NOT NULL,
    "TutorId" NUMBER(10) NOT NULL,
    CONSTRAINT "PK_PETS" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_PETS_TUTORES_TutorId" FOREIGN KEY ("TutorId") REFERENCES "TUTORES" ("Id") ON DELETE CASCADE
)';
END;
/

BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"CONSULTAS" (
    "Id" NUMBER(10) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "Data" TIMESTAMP(7) NOT NULL,
    "Descricao" NVARCHAR2(2000) NOT NULL,
    "Veterinario" NVARCHAR2(2000) NOT NULL,
    "Observacoes" NVARCHAR2(2000),
    "PetId" NUMBER(10) NOT NULL,
    CONSTRAINT "PK_CONSULTAS" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_CONSULTAS_PETS_PetId" FOREIGN KEY ("PetId") REFERENCES "PETS" ("Id") ON DELETE CASCADE
)';
END;
/

BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"VACINAS" (
    "Id" NUMBER(10) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "Nome" NVARCHAR2(2000) NOT NULL,
    "DataAplicacao" TIMESTAMP(7) NOT NULL,
    "ProximaDose" TIMESTAMP(7),
    "Aplicada" NUMBER(1) NOT NULL,
    "PetId" NUMBER(10) NOT NULL,
    CONSTRAINT "PK_VACINAS" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_VACINAS_PETS_PetId" FOREIGN KEY ("PetId") REFERENCES "PETS" ("Id") ON DELETE CASCADE
)';
END;
/

CREATE INDEX "IX_CONSULTAS_PetId" ON "CONSULTAS" ("PetId")
/

